830	+/*
831	+ * How the race view follows the player's car: it keeps the car on screen and leaves more room in
832	+ * front of the car than behind it, whichever way the car is heading.
833	+ *
834	+ * The camera updater used by the race screen is driven with a car standing still in the middle of
835	+ * a large track, facing various directions, and the resulting camera is inspected.
836	+ */
837	+package com.agateau.pixelwheels.racescreen;
838	+
839	+import static org.junit.Assert.assertTrue;
840	+import static org.mockito.Mockito.mock;
841	+import static org.mockito.Mockito.when;
842	+
843	+import com.agateau.pixelwheels.GameWorld;
