849	+import org.junit.Test;
850	+import org.junit.runner.RunWith;
851	+import org.junit.runners.JUnit4;
852	+
853	+@RunWith(JUnit4.class)
854	+public class RacerCameraTest {
855	+    private static final float[] HEADINGS = {0, 45, 90, 135, 180, 225, 270, 315};
856	+    private static final Vector2 CAR = new Vector2(500, 500);
857	+
858	+    /** Returns where the view is centered, relative to the car. */
859	+    private static Vector2 viewOffset(float heading) {
860	+        Track track = mock(Track.class);
861	+        when(track.getMapWidth()).thenReturn(1000f);
862	+        when(track.getMapHeight()).thenReturn(1000f);
863	+        GameWorld world = mock(GameWorld.class);
864	+        when(world.getTrack()).thenReturn(track);
865	+
866	+        Vehicle vehicle = mock(Vehicle.class);
867	+        when(vehicle.getPosition()).thenReturn(new Vector2(CAR));
868	+        when(vehicle.getX()).thenReturn(CAR.x);
869	+        when(vehicle.getY()).thenReturn(CAR.y);
870	+        when(vehicle.getAngle()).thenReturn(heading);
871	+        when(vehicle.getSpeed()).thenReturn(0f);
872	+        Racer racer = mock(Racer.class);
873	+        when(racer.getVehicle()).thenReturn(vehicle);
874	+        when(racer.getCameraAngle()).thenReturn(heading);
875	+        when(racer.getPosition()).thenReturn(new Vector2(CAR));
876	+        when(racer.getX()).thenReturn(CAR.x);
877	+        when(racer.getY()).thenReturn(CAR.y);
878	+
879	+        OrthographicCamera camera = new OrthographicCamera();
880	+        RacerCameraUpdater updater = new RacerCameraUpdater(world, racer);
881	+        updater.init(camera, 1920, 1080);
882	+        updater.update(CameraUpdater.IMMEDIATE);
883	+
884	+        float halfW = camera.viewportWidth * camera.zoom / 2;
885	+        float halfH = camera.viewportHeight * camera.zoom / 2;
886	+        Vector2 offset = new Vector2(camera.position.x, camera.position.y).sub(CAR);
887	+        assertTrue(
888	+                "heading " + heading + "°: the car is out of the view (view offset " + offset + ")",
889	+                Math.abs(offset.x) < halfW && Math.abs(offset.y) < halfH);
890	+        return offset;
891	+    }
892	+
893	+    private static float angleBetween(Vector2 direction, float angleDeg) {
894	+        float delta = (direction.angleDeg() - angleDeg) % 360;
895	+        if (delta < -180) {
896	+            delta += 360;
897	+        } else if (delta > 180) {
898	+            delta -= 360;
899	+        }
900	+        return Math.abs(delta);
901	+    }
902	+
903	+    @Test
904	+    public void viewLooksAheadOfTheCarWhicheverWayItHeads() {
905	+        for (float heading : HEADINGS) {
906	+            Vector2 offset = viewOffset(heading);
907	+            assertTrue(
908	+                    "heading " + heading + "°: the view should show more of the road ahead of the"
909	+                            + " car than behind it (view offset " + offset + ")",
910	+                    offset.len() > 1);
911	+            assertTrue(
912	+                    "heading " + heading + "°: the view is shifted towards " + offset.angleDeg()
913	+                            + "° instead of towards where the car is heading",
914	+                    angleBetween(offset, heading) < 5);
915	+        }
916	+    }
917	+
918	+    @Test
919	+    public void viewKeepsTheCarOnScreen() {
920	+        for (float heading : HEADINGS) {
921	+            viewOffset(heading);
922	+        }
923	+    }
