teau.pixelwheels.GameWorld.VELOCITY_ITERATIONS;\n+import static org.junit.Assert.assertFalse;\n+import static org.junit.Assert.assertTrue;\n+import static org.mockito.Mockito.mock;\n+import static org.mockito.Mockito.when;\n+\n+import com.agateau.pixelwheels.Assets;\n+import com.agateau.pixelwheels.GameWorld;\n+import com.agateau.pixelwheels.ZLevel;\n+import com.agateau.pixelwheels.racer.Racer;\n+import com.agateau.pixelwheels.racer.Vehicle;\n+import com.agateau.pixelwheels.racer.VehicleRenderer;\n+import com.agateau.pixelwheels.sound.AudioManager;\n+import com.agateau.pixelwheels.testutils.DrawRecorder;\n+import com.badlogic.gdx.graphics.Texture;\n+import com.badlogic.gdx.graphics.g2d.Animation;\n+import com.badlogic.gdx.graphics.g2d.TextureRegion;\n+import com.badlogic.gdx.math.MathUtils;\n+import com.badlogic.gdx.math.Rectangle;\n+import com.badlogic.gdx.math.Vector2;\n+import com.badlogic.gdx.physics.box2d.Body;\n+import com.badlogic.gdx.physics.box2d.BodyDef;\n+import com.badlogic.gdx.physics.box2d.Filter;\n+import com.badlogic.gdx.physics.box2d.Fixture;\n+import com.badlogic.gdx.physics.box2d.PolygonShape;\n+import com.badlogic.gdx.physics.box2d.World;\n+import com.badlogic.gdx.utils.Array;\n+import java.lang.reflect.Field;\n+import java.util.ArrayList;\n+import java.util.List;\n+import org.junit.Test;\n+import org.junit.runner.RunWith;\n+import org.junit.runners.JUnit4;\n+\n+@RunWith(JUnit4.class)\n+public class RocketTest {\n+    // Car headings (degrees, counter-clockwise from +X) the scenarios are played with.\n+    private static final float[] HEADINGS = {30, 90, 135, 200, 290};\n+    private static final float ANGLE_TOLERANCE = 5;\n+    private static final Rectangle VIEW = new Rectangle(-1000, -1000, 3000, 3000);\n+\n+    private static class Scene {\n+        World world;\n+        Body carBody;\n+        Texture rocketTexture;\n+        Texture flameTexture;\n+        Missile missile;\n+\n+        void step(int count) {\n+            for (int i = 0; i < count; ++i) {\n+                world.step(BOX2D_TIME_STEP, VELOCITY_ITERATIONS, POSITION_ITERATIONS);\n+                missile.act(BOX2D_TIME_STEP);\n+            }\n+        }\n+\n+        DrawRecorder draw() {\n+            DrawRecorder batch = new DrawRecorder();\n+            for (ZLevel zLevel : ZLevel.values()) {\n+                missile.draw(batch, zLevel, VIEW);\n+            }\n+            return batch;\n+        }\n+\n+        /** The rocket sprite itself: the untinted quad(s) using the rocket image. */\n+        DrawRecorder.Quad rocketSprite(DrawRecorder batch) {\n+            List<DrawRecorder.Quad> list = new ArrayList<>();\n+            for (DrawRecorder.Quad quad : batch.quadsOf(rocketTexture)) {\n+                if (!quad.isShadowLike()) {\n+                    list.add(quad);\n+                }\n+            }\n+            assertFalse(\"the rocket should be drawn\", list.isEmpty());\n+            DrawRecorder.Quad first = list.get(0);\n+            for (DrawRecorder.Quad other : list) {\n+                assertTrue(\n+                        \"the rocket is drawn several times, at different places: \" + list,\n+                        other.center().dst(first.center()) < 0.05f\n+                                && angleBetween(other.imageXAxis(), first.imageXAxis()) < 1);\n+            }\n+            return first;\n+        }\n+    }\n+\n+    private static Texture texture() {\n+        Texture texture = mock(Texture.class);\n+        when(texture.getWidth()).thenReturn(64);\n+        when(texture.getHeight()).thenReturn(64);\n+        return texture;\n+    }\n+\n+    private static Scene createScene(float headingDeg) throws Exception {\n+        Scene scene = new Scene();\n+        scene.world = new World(new Vector2(0, 0), true);\n+\n+        BodyDef bodyDef = new BodyDef();\n+        bodyDef.type = BodyDef.BodyType.DynamicBody;\n+        bodyDef.position.set(20, 20);\n+        bodyDef.angle = headingDeg * MathUtils.degRad;\n+        Body carBody = scene.world.createBody(bodyDef);\n+        PolygonShape shape = new PolygonShape();\n+        shape.setAsBox(1.4f, 0.75f);\n+        Fixture fixture = carBody.createFixture(shape, 1f);\n+        shape.dispose();\n+        // The car body only carries the rocket here: keep it out of any collision.\n+        Filter filter = new Filter();\n+        filter.categoryBits = 0x4000;\n+        filter.maskBits = 0;\n+        fixture.setFilterData(filter);\n+        scene.carBody = carBody;\n+\n+        Vehicle vehicle = mock(Vehicle.class);\n+        when(vehicle.getBody()).thenReturn(carBody);\n+        when(vehicle.getX()).thenAnswer(i -> carBody.getPosition().x);\n+        when(vehicle.getY()).thenAnswer(i -> carBody.getPosition().y);\n+        when(vehicle.getPosition()).thenAnswer(i -> carBody.getPosition());\n+        when(vehicle.getAngle())\n+                .thenAnswer(i -> ((carBody.getAngle() * MathUtils.radDeg) % 360 + 360) % 360);\n+        Racer racer = mock(Racer.class);\n+        when(racer.getVehicle()).thenReturn(vehicle);\n+        when(racer.getPosition()).thenAnswer(i -> carBody.getPosition());\n+        carBody.setUserData(racer);\n+\n+        GameWorld gameWorld = mock(GameWorld.class);\n+        when(gameWorld.getBox2DWorld()).thenReturn(scene.world);\n+\n+        scene.rocketTexture = texture();\n+        scene.flameTexture = texture();\n+        Array<TextureRegion> flameFrames = new Array<>();\n+        flameFrames.add(new TextureRegion(scene.flameTexture, 0, 0, 7, 14));\n+        flameFrames.add(new TextureRegion(scene.flameTexture, 8, 0, 7, 14));\n+        Assets assets = mock(Assets.class);\n+        setField(assets, \"missile\", new TextureRegion(scene.rocketTexture, 0, 0, 44, 13));\n+        setField(assets, \"target\", new TextureRegion(texture(), 0, 0, 16, 16));\n+        setField(assets, \"turboFlame\", new Animation<>(0.1f, flameFrames));\n+        // A real Racer always has a VehicleRenderer; code drawing what it carries may use it.\n+        when(racer.getVehicleRenderer()).thenReturn(new VehicleRenderer(assets, vehicle));\n+\n+        scene.missile = Missile.create(assets, gameWorld, mock(AudioManager.class), racer);\n+        return scene;\n+    }\n+\n+    private static void setField(Object target, String name, Object value) throws Exception {\n+        Field field = Assets.class.getDeclaredField(name);\n+        field.setAccessible(true);\n+        field.set(target, value);\n+    }\n+\n+    /** Absolute difference between two angles in degrees, in [0, 180]. */\n+    private static float angleBetween(Vector2 direction, float angleDeg) {\n+        float delta = (direction.angleDeg() - angleDeg) % 360;\n+        if (delta < -180) {\n+            delta += 360;\n+        } else if (delta > 180) {\n+            delta -= 360;\n+        }\n+        return Math.abs(delta);\n+    }\n+\n+    private static float angleBetween(Vector2 a, Vector2 b) {\n+        return angleBetween(a, b.angleDeg());\n+    }\n+\n+    @Test\n+    public void carriedRocketPointsWhereTheCarPoints() throws Exception {\n+        for (float heading : HEADINGS) {\n+            Scene scene = createScene(heading);\n+            scene.step(20);\n+            DrawRecorder.Quad rocket = scene.rocketSprite(scene.draw());\n+            Vector2 nose = rocket.imageXAxis();\n+            assertTrue(\n+                    \"car heading \" + heading + \"°: the rocket it carries is drawn pointing \"\n+                            + nose.angleDeg() + \"°\",\n+                    angleBetween(nose, heading) < ANGLE_TOLERANCE);\n+        }\n+    }\n+\n+    @Test\n+    public void firedRocketFliesWhereTheCarPoints() throws Exception {\n+        for (float heading : HEADINGS) {\n+            Scene scene = createScene(heading);\n+            scene.step(10);\n+            scene.missile.shoot();\n+            Vector2 start = new Vector2(scene.missile.getX(), scene.missile.getY());\n+            scene.step(30);\n+            Vector2 travel =\n+                    new Vector2(scene.missile.getX(), scene.missile.getY()).sub(start);\n+            assertTrue(\n+                    \"car heading \" + heading + \"°: the fired rocket barely moved (\" + travel + \")\",\n+                    travel.len() > 5);\n+            assertTrue(\n+                    \"car heading \" + heading + \"°: the fired rocket flew towards \"\n+                            + travel.angleDeg() + \"°\",\n+                    angleBetween(travel, heading) < ANGLE_TOLERANCE);\n+            Vector2 nose = scene.rocketSprite(scene.draw()).imageXAxis();\n+            assertTrue(\n+                    \"car heading \" + heading + \"°: the flying rocket is drawn pointing \"\n+                            + nose.angleDeg() + \"° while flying towards \" + travel.angleDeg() + \"°\",\n+                    angleBetween(nose, travel) < ANGLE_TOLERANCE);\n+        }\n+    }\n+\n+    @Test\n+    public void rocketExhaustComesOutOfItsTail() throws Exception {\n+        for (float heading : HEADINGS) {\n+            Scene scene = createScene(heading);\n+            scene.step(10);\n+            scene.missile.shoot();\n+            scene.step(3);\n+            DrawRecorder batch = scene.draw();\n+            DrawRecorder.Quad rocket = scene.rocketSprite(batch);\n+            List<DrawRecorder.Quad> flames = batch.quadsOf(scene.flameTexture);\n+            assertFalse(\n+                    \"car heading \" + heading + \"°: a fired rocket should show its exhaust\",\n+                    flames.isEmpty());\n+\n+            Vector2 axis = rocket.imageXAxis();\n+            float length = rocket.imageWidth();\n+            for (DrawRecorder.Quad flame : flames) {\n+                Vector2 offset = flame.center().sub(rocket.center());\n+                float along = offset.dot(axis);\n+                float aside = Math.abs(offset.crs(axis));\n+                assertTrue(\n+                        \"car heading \" + heading + \"°: the exhaust should be behind the rocket's\"\n+                                + \" tail, it is \" + along + \" along the rocket axis (rocket\"\n+                                + \" length \" + length + \")\",\n+                        along < -0.45f * length);\n+                assertTrue(\n+                        \"car heading \" + heading + \"°: the exhaust should be in line with the\"\n+                                + \" rocket, it is \" + aside + \" to the side (rocket length \"\n+                                + length + \")\",\n+                        aside < 0.15f * length);\n+            }\n+        }\n+    }\n+\n+    @Test\n+    public void rocketShadowHasTheRocketsOrientation() throws Exception {\n+        for (float heading : HEADINGS) {\n+            for (boolean fired : new boolean[] {false, true}) {\n+                Scene scene = createScene(heading);\n+                scene.step(10);\n+                if (fired) {\n+                    scene.missile.shoot();\n+                    scene.step(5);\n+                }\n+                DrawRecorder batch = scene.draw();\n+                DrawRecorder.Quad rocket = scene.rocketSprite(batch);\n+                List<DrawRecorder.Quad> shadows = new ArrayList<>();\n+                for (DrawRecorder.Quad quad : batch.quadsOf(scene.rocketTexture)) {\n+                    if (quad.isShadowLike()) {\n+                        shadows.add(quad);\n+                    }\n+                }\n+                String what = \"car heading \" + heading + \"°, \" + (fired ? \"fired\" : \"carried\");\n+                assertFalse(what + \": the rocket should cast a shadow\", shadows.isEmpty());\n+                for (DrawRecorder.Quad shadow : shadows) {\n+                    assertTrue(\n+                            what + \": rocket drawn at \" + rocket.imageXAxis().angleDeg()\n+                                    + \"° but its shadow at \" + shadow.imageXAxis().angleDeg()\n+                                    + \"°\",\n+                            angleBetween(shadow.imageXAxis(), rocket.imageXAxis()) < 2);\n+                    assertTrue(\n+                            what + \": the shadow should stay right under the rocket\",\n+                            shadow.center().dst(rocket.center()) < 0.5f * rocket.imageWidth());\n+                }\n+            }\n+        }\n+    }\n+}\ndiff --git a/core-tests/src/com/agateau/pixelwheels/racer/VehicleShadowTest.java b/core-tests/src/com/agateau/pixelwheels/racer/VehicleShadowTest.java\nnew file mode 100755\nindex 0000000..beab7f6\n--- /dev/null\n+++ b/core-tests/src/com/agateau/pixelwheels/racer/VehicleShadowTest.java\n@@ -0,0 +1,110 @@\n+/*\n+ * A car on the ground casts its shadow the same way as every other object of the game: slightly\n+ * down and to the right of it (the same side the rocket shadows, obstacle shadows and the map's\n+ * buildings, trees and bridges cast theirs).\n+ *\n+ * The real VehicleRenderer is drawn, at every drawing level, through a Batch that records every\n+ * textured quad (see DrawRecorder). The vehicle is pre-rendered in an off-screen cell, so the test\n+ * runs inside a real hidden GL context (see GlContext).\n+ */\n+package com.agateau.pixelwheels.racer;\n+\n+import static org.junit.Assert.assertFalse;\n+import static org.junit.Assert.assertTrue;\n+import static org.mockito.ArgumentMatchers.anyFloat;\n+import static org.mockito.Mockito.mock;\n+import static org.mockito.Mockito.when;\n+\n+import com.agateau.pixelwheels.Assets;\n+import com.agateau.pixelwheels.ZLevel;\n+import com.agateau.pixelwheels.gameobject.CellFrameBufferManager;\n+import com.agateau.pixelwheels.testutils.DrawRecorder;\n+import com.agateau.pixelwheels.testutils.GlContext;\n+import com.badlogic.gdx.graphics.Texture;\n+import com.badlogic.gdx.graphics.g2d.TextureRegion;\n+import com.badlogic.gdx.math.Rectangle;\n+import com.badlogic.gdx.math.Vector2;\n+import com.badlogic.gdx.utils.Array;\n+import java.util.ArrayList;\n+import java.util.List;\n+import org.junit.Test;\n+import org.junit.runner.RunWith;\n+import org.junit.runners.JUnit4;\n+\n+@RunWith(JUnit4.class)\n+public class VehicleShadowTest {\n+    private static final Vector2 POS = new Vector2(30, 30);\n+\n+    @Test(timeout = 60000)\n+    public void vehicleShadowFallsLikeEveryOtherShadow() {\n+        GlContext.run(\n+                () -> {\n+                    // The light does not turn with the car: check several headings.\n+                    for (float heading : new float[] {0, 90, 200, 315}) {\n+                        checkShadow(heading);\n+                    }\n+                });\n+    }\n+\n+    private static void checkShadow(float heading) {\n+        Texture texture = mock(Texture.class);\n+        when(texture.getWidth()).thenReturn(64);\n+        when(texture.getHeight()).thenReturn(64);\n+        TextureRegion region = new TextureRegion(texture, 0, 0, 30, 52);\n+\n+        Vehicle vehicle = mock(Vehicle.class);\n+        when(vehicle.getWheelInfos()).thenReturn(new Array<>());\n+        when(vehicle.getRegion(anyFloat())).thenReturn(region);\n+        when(vehicle.getPosition()).thenReturn(new Vector2(POS));\n+        when(vehicle.getX()).thenReturn(POS.x);\n+        when(vehicle.getY()).thenReturn(POS.y);\n+        when(vehicle.getAngle()).thenReturn(heading);\n+        when(vehicle.getZ()).thenReturn(0f);\n+        when(vehicle.isFlying()).thenReturn(false);\n+        when(vehicle.isFalling()).thenReturn(false);\n+        when(vehicle.getTurboTime()).thenReturn(-1f);\n+\n+        VehicleRenderer renderer = new VehicleRenderer(mock(Assets.class), vehicle);\n+        renderer.init(new CellFrameBufferManager());\n+\n+        DrawRecorder batch = new DrawRecorder();\n+        Rectangle view = new Rectangle(0, 0, 60, 60);\n+        for (ZLevel zLevel : ZLevel.values()) {\n+            renderer.draw(batch, zLevel, view);\n+        }\n+\n+        String what = \"heading \" + heading + \"°: \";\n+        List<DrawRecorder.Quad> bodies = new ArrayList<>();\n+        for (DrawRecorder.Quad quad : batch.quads()) {\n+            if (!quad.isShadowLike()) {\n+                bodies.add(quad);\n+            }\n+        }\n+        assertFalse(what + \"the car should be drawn\", bodies.isEmpty());\n+        DrawRecorder.Quad body = bodies.get(0);\n+        assertTrue(\n+                what + \"the car should be drawn where it is (\" + body.center() + \")\",\n+                body.center().dst(POS) < 0.01f);\n+\n+        // Shadows are darkened copies of the car image (same texture as the car itself).\n+        List<DrawRecorder.Quad> shadows = new ArrayList<>();\n+        for (DrawRecorder.Quad quad : batch.quadsOf(body.texture)) {\n+            if (quad.isShadowLike()) {\n+                shadows.add(quad);\n+            }\n+        }\n+        assertFalse(what + \"the car should cast a shadow\", shadows.isEmpty());\n+        for (DrawRecorder.Quad shadow : shadows) {\n+            Vector2 offset = shadow.center().sub(body.center());\n+            assertTrue(\n+                    what\n+                            + \"the car shadow should fall down and to the right of the car, like\"\n+                            + \" every other shadow; it is offset by \"\n+                            + offset,\n+                    offset.x > 0.05f && offset.y < -0.05f);\n+            assertTrue(\n+                    what + \"the shadow of a car on the ground should stay close to it: \" + offset,\n+                    offset.len() < 1);\n+        }\n+    }\n+}\ndiff --git a/core-tests/src/com/agateau/pixelwheels/racescreen/MissileZOrderTest.java b/core-tests/src/com/agateau/pixelwheels/racescreen/MissileZOrderTest.java\nnew file mode 100644\nindex 0000000..2f33441\n--- /dev/null\n+++ b/core-tests/src/com/agateau/pixelwheels/racescreen/MissileZOrderTest.java\n@@ -0,0 +1,397 @@\n+/*\n+ * Tests for https://github.com/agateau/pixelwheels/issues/362 (\"the rocket weapon on the vehicles\n+ * is shown on top of the race map elements\": footbridges, bridge sides, tree clusters, huts).\n+ *\n+ * They drive the real GameRenderer rendering loop with a real (but code-built, not loaded from an\n+ * asset file) track made of one background layer and one foreground layer, and real game objects,\n+ * through a Batch that records every textured quad in the order it is drawn. What is checked is\n+ * the painter's-algorithm order the player sees: drawn earlier means drawn underneath.\n+ *\n+ * GameRenderer eagerly creates a ShapeRenderer and a CellFrameBufferManager (which allocates a\n+ * real FrameBuffer) in its constructor, so these tests run inside a real, hidden desktop GL\n+ * context (see GlContext).\n+ */\n+package com.agateau.pixelwheels.racescreen;\n+\n+import static org.junit.Assert.assertFalse;\n+import static org.junit.Assert.assertTrue;\n+import static org.mockito.ArgumentMatchers.anyFloat;\n+import static org.mockito.Mockito.mock;\n+import static org.mockito.Mockito.when;\n+\n+import com.agateau.pixelwheels.Assets;\n+import com.agateau.pixelwheels.GamePlay;\n+import com.agateau.pixelwheels.GameWorld;\n+import com.agateau.pixelwheels.ZLevel;\n+import com.agateau.pixelwheels.bonus.Missile;\n+import com.agateau.pixelwheels.gameobject.CellFrameBufferManager;\n+import com.agateau.pixelwheels.gameobject.CellFrameBufferUser;\n+import com.agateau.pixelwheels.gameobject.GameObject;\n+import com.agateau.pixelwheels.gameobject.GameObjectAdapter;\n+import com.agateau.pixelwheels.map.Track;\n+import com.agateau.pixelwheels.racer.Racer;\n+import com.agateau.pixelwheels.racer.Vehicle;\n+import com.agateau.pixelwheels.racer.VehicleRenderer;\n+import com.agateau.pixelwheels.sound.AudioManager;\n+import com.agateau.pixelwheels.testutils.DrawRecorder;\n+import com.agateau.pixelwheels.testutils.GlContext;\n+import com.badlogic.gdx.graphics.Texture;\n+import com.badlogic.gdx.graphics.g2d.Batch;\n+import com.badlogic.gdx.graphics.g2d.TextureRegion;\n+import com.badlogic.gdx.graphics.glutils.FrameBuffer;\n+import com.badlogic.gdx.maps.tiled.TiledMap;\n+import com.badlogic.gdx.maps.tiled.TiledMapTileLayer;\n+import com.badlogic.gdx.maps.tiled.tiles.StaticTiledMapTile;\n+import com.badlogic.gdx.math.MathUtils;\n+import com.badlogic.gdx.math.Rectangle;\n+import com.badlogic.gdx.math.Vector2;\n+import com.badlogic.gdx.physics.box2d.Body;\n+import com.badlogic.gdx.physics.box2d.BodyDef;\n+import com.badlogic.gdx.physics.box2d.Filter;\n+import com.badlogic.gdx.physics.box2d.Fixture;\n+import com.badlogic.gdx.physics.box2d.PolygonShape;\n+import com.badlogic.gdx.physics.box2d.World;\n+import com.badlogic.gdx.utils.Array;\n+import com.badlogic.gdx.utils.PerformanceCounters;\n+import java.lang.reflect.Field;\n+import java.util.List;\n+import org.junit.Test;\n+import org.junit.runner.RunWith;\n+import org.junit.runners.JUnit4;\n+\n+@RunWith(JUnit4.class)\n+public class MissileZOrderTest {\n+    private static final int TILE_PX = 20;\n+    private static final int MAP_TILES = 64;\n+    // World-space position (after Constants.UNIT_FOR_PIXEL scaling) of the objects and of the\n+    // foreground tile above them. Matches the middle of the viewport set up below.\n+    private static final float POSITION = 30f;\n+\n+    private static Texture texture() {\n+        Texture texture = mock(Texture.class);\n+        when(texture.getWidth()).thenReturn(64);\n+        when(texture.getHeight()).thenReturn(64);\n+        return texture;\n+    }\n+\n+    /**\n+     * A car carrying a rocket (picked up, not fired yet) drives under a foreground map element:\n+     * within one rendered frame, every quad of the rocket must be drawn before the foreground\n+     * layer, so the rocket ends up underneath it together with the car.\n+     */\n+    @Test(timeout = 60000)\n+    public void missileIsDrawnBeforeForegroundLayer() {\n+        GlContext.run(\n+                () -> {\n+                    Texture fgTexture = texture();\n+                    Texture missileTexture = texture();\n+                    World box2DWorld = new World(new Vector2(0, 0), true);\n+                    Missile missile = buildCarriedMissile(box2DWorld, missileTexture);\n+\n+                    DrawRecorder batch = renderOneFrame(fgTexture, box2DWorld, missile);\n+\n+                    List<DrawRecorder.Quad> fg = batch.quadsOf(fgTexture);\n+                    List<DrawRecorder.Quad> rocket = batch.quadsOf(missileTexture);\n+                    assertFalse(\"the foreground layer should be drawn\", fg.isEmpty());\n+                    assertFalse(\"the carried rocket should be drawn\", rocket.isEmpty());\n+                    int firstFg = fg.get(0).index;\n+                    for (DrawRecorder.Quad quad : rocket) {\n+                        assertTrue(\n+                                \"The rocket (and its shadow) should be drawn before the foreground\"\n+                                        + \" layer, so that it appears underneath it instead of\"\n+                                        + \" over it: \"\n+                                        + quad\n+                                        + \" drawn after foreground quad #\"\n+                                        + firstFg,\n+                                quad.index < firstFg);\n+                    }\n+                });\n+    }\n+\n+    /**\n+     * Guard: the rescue helicopter keeps flying *above* the foreground layer, as it does at the\n+     * base commit. A fix that drew every flying object before the foreground layer would break it.\n+     */\n+    @Test(timeout = 60000)\n+    public void helicopterIsDrawnAfterForegroundLayer() {\n+        GlContext.run(\n+                () -> {\n+                    Texture fgTexture = texture();\n+                    Texture helicopterTexture = texture();\n+                    Helicopter helicopter = buildHelicopter(helicopterTexture);\n+\n+                    DrawRecorder batch =\n+                            renderOneFrame(\n+                                    fgTexture, new World(new Vector2(0, 0), true), helicopter);\n+\n+                    List<DrawRecorder.Quad> fg = batch.quadsOf(fgTexture);\n+                    assertFalse(\"the foreground layer should be drawn\", fg.isEmpty());\n+                    int lastFg = fg.get(fg.size() - 1).index;\n+                    boolean bodyDrawn = false;\n+                    for (DrawRecorder.Quad quad : batch.quadsOf(helicopterTexture)) {\n+                        if (quad.isShadowLike()) {\n+                            continue;\n+                        }\n+                        bodyDrawn = true;\n+                        assertTrue(\n+                                \"The rescue helicopter should keep being drawn over the\"\n+                                        + \" foreground layer: \"\n+                                        + quad,\n+                                quad.index > lastFg);\n+                    }\n+                    assertTrue(\"the helicopter should be drawn\", bodyDrawn);\n+                });\n+    }\n+\n+    /**\n+     * Guard: a vehicle lifted by the rescue helicopter keeps being drawn *above* the foreground\n+     * layer, as it does at the base commit (it is carried in the air together with the helicopter).\n+     */\n+    @Test(timeout = 60000)\n+    public void liftedVehicleIsDrawnAfterForegroundLayer() {\n+        GlContext.run(\n+                () -> {\n+                    Texture fgTexture = texture();\n+                    Texture vehicleTexture = texture();\n+                    World box2DWorld = new World(new Vector2(0, 0), true);\n+                    LiftedVehicle lifted = new LiftedVehicle(box2DWorld, vehicleTexture);\n+\n+                    DrawRecorder batch = renderOneFrame(fgTexture, box2DWorld, lifted);\n+\n+                    List<DrawRecorder.Quad> fg = batch.quadsOf(fgTexture);\n+                    assertFalse(\"the foreground layer should be drawn\", fg.isEmpty());\n+                    int lastFg = fg.get(fg.size() - 1).index;\n+                    boolean bodyDrawn = false;\n+                    for (DrawRecorder.Quad quad : batch.quads()) {\n+                        // On screen the vehicle is drawn from its pre-rendered cell: skip the\n+                        // foreground tiles, the off-screen cell painting and the shadow.\n+                        if (quad.texture == fgTexture\n+                                || quad.texture == vehicleTexture\n+                                || quad.isShadowLike()) {\n+                            continue;\n+                        }\n+                        bodyDrawn = true;\n+                        assertTrue(\n+                                \"A vehicle lifted by the helicopter should keep being drawn over\"\n+                                        + \" the foreground layer: \"\n+                                        + quad,\n+                                quad.index > lastFg);\n+                    }\n+                    assertTrue(\"the lifted vehicle should be drawn\", bodyDrawn);\n+                });\n+    }\n+\n+    /** A vehicle in the air (lifted by the helicopter), rendered by the real VehicleRenderer. */\n+    private static class LiftedVehicle extends GameObjectAdapter implements CellFrameBufferUser {\n+        private final VehicleRenderer mRenderer;\n+\n+        LiftedVehicle(World world, Texture texture) {\n+            BodyDef bodyDef = new BodyDef();\n+            bodyDef.type = BodyDef.BodyType.DynamicBody;\n+            bodyDef.position.set(POSITION, POSITION);\n+            bodyDef.angle = 90 * MathUtils.degRad;\n+            Body body = world.createBody(bodyDef);\n+\n+            Vehicle vehicle = mock(Vehicle.class);\n+            when(vehicle.getBody()).thenReturn(body);\n+            when(vehicle.getWheelInfos()).thenReturn(new Array<>());\n+            when(vehicle.getRegion(anyFloat())).thenReturn(new TextureRegion(texture, 0, 0, 30, 52));\n+            when(vehicle.getPosition()).thenReturn(new Vector2(POSITION, POSITION));\n+            when(vehicle.getX()).thenReturn(POSITION);\n+            when(vehicle.getY()).thenReturn(POSITION);\n+            when(vehicle.getAngle()).thenReturn(90f);\n+            when(vehicle.isFlying()).thenReturn(true);\n+            when(vehicle.isFalling()).thenReturn(false);\n+            when(vehicle.getZ()).thenReturn(0.5f);\n+            when(vehicle.getTurboTime()).thenReturn(-1f);\n+            mRenderer = new VehicleRenderer(mock(Assets.class), vehicle);\n+        }\n+\n+        @Override\n+        public void init(CellFrameBufferManager manager) {\n+            mRenderer.init(manager);\n+        }\n+\n+        @Override\n+        public void drawToCell(Batch batch, Rectangle viewBounds) {\n+            mRenderer.drawToCell(batch, viewBounds);\n+        }\n+\n+        @Override\n+        public void act(float delta) {}\n+\n+        @Override\n+        public void draw(Batch batch, ZLevel zLevel, Rectangle viewBounds) {\n+            mRenderer.draw(batch, zLevel, viewBounds);\n+        }\n+\n+        @Override\n+        public float getX() {\n+            return POSITION;\n+        }\n+\n+        @Override\n+        public float getY() {\n+            return POSITION;\n+        }\n+    }\n+\n+    private static DrawRecorder renderOneFrame(\n+            Texture fgTexture, World box2DWorld, GameObject object) {\n+        boolean oldFreeCamera = GamePlay.instance.freeCamera;\n+        GamePlay.instance.freeCamera = true;\n+        try {\n+            return renderOneFrameWithFreeCamera(fgTexture, box2DWorld, object);\n+        } finally {\n+            GamePlay.instance.freeCamera = oldFreeCamera;\n+        }\n+    }\n+\n+    private static DrawRecorder renderOneFrameWithFreeCamera(\n+            Texture fgTexture, World box2DWorld, GameObject object) {\n+        FakeTrack track = new FakeTrack(buildMap(fgTexture));\n+\n+        GameWorld gameWorld = mock(GameWorld.class);\n+        when(gameWorld.getTrack()).thenReturn(track);\n+        when(gameWorld.getBox2DWorld()).thenReturn(box2DWorld);\n+        Array<GameObject> gameObjects = new Array<>();\n+        gameObjects.add(object);\n+        when(gameWorld.getActiveGameObjects()).thenReturn(gameObjects);\n+\n+        DrawRecorder batch = new DrawRecorder();\n+        GameRenderer renderer =\n+                new GameRenderer(gameWorld, /* racer= */ null, batch, new PerformanceCounters());\n+        renderer.setScreenRect(0, 0, 60, 60);\n+        renderer.onAboutToStart();\n+\n+        // Render once so the free camera settles, then record exactly one frame: checking the\n+        // order across several frames would let one frame's draws satisfy another frame's check.\n+        renderer.render(0f);\n+        batch.clear();\n+        renderer.render(0f);\n+        return batch;\n+    }\n+\n+    private static Missile buildCarriedMissile(World world, Texture missileTexture)\n+            throws Exception {\n+        BodyDef bodyDef = new BodyDef();\n+        bodyDef.type = BodyDef.BodyType.DynamicBody;\n+        bodyDef.position.set(POSITION, POSITION);\n+        bodyDef.angle = 90 * MathUtils.degRad;\n+        Body carBody = world.createBody(bodyDef);\n+        PolygonShape shape = new PolygonShape();\n+        shape.setAsBox(1.4f, 0.75f);\n+        Fixture fixture = carBody.createFixture(shape, 1f);\n+        shape.dispose();\n+        Filter filter = new Filter();\n+        filter.categoryBits = 0x4000;\n+        filter.maskBits = 0;\n+        fixture.setFilterData(filter);\n+\n+        Vehicle vehicle = mock(Vehicle.class);\n+        when(vehicle.getBody()).thenReturn(carBody);\n+        when(vehicle.getX()).thenReturn(POSITION);\n+        when(vehicle.getY()).thenReturn(POSITION);\n+        when(vehicle.getPosition()).thenReturn(new Vector2(POSITION, POSITION));\n+        when(vehicle.getAngle()).thenReturn(90f);\n+        Racer racer = mock(Racer.class);\n+        when(racer.getVehicle()).thenReturn(vehicle);\n+        carBody.setUserData(racer);\n+\n+        GameWorld gameWorld = mock(GameWorld.class);\n+        when(gameWorld.getBox2DWorld()).thenReturn(world);\n+\n+        Assets assets = mock(Assets.class);\n+        setField(assets, Assets.class, \"missile\", new TextureRegion(missileTexture, 44, 13));\n+        setField(assets, Assets.class, \"target\", new TextureRegion(missileTexture, 16, 16));\n+        // A real Racer always has a VehicleRenderer; code drawing what it carries may use it.\n+        when(racer.getVehicleRenderer()).thenReturn(new VehicleRenderer(assets, vehicle));\n+        return Missile.create(assets, gameWorld, mock(AudioManager.class), racer);\n+    }\n+\n+    private static Helicopter buildHelicopter(Texture frameBufferTexture) throws Exception {\n+        Helicopter helicopter = Helicopter.class.getDeclaredConstructor().newInstance();\n+\n+        FrameBuffer frameBuffer = mock(FrameBuffer.class);\n+        when(frameBuffer.getWidth()).thenReturn(TILE_PX);\n+        when(frameBuffer.getHeight()).thenReturn(TILE_PX);\n+        when(frameBuffer.getColorBufferTexture()).thenReturn(frameBufferTexture);\n+        setField(helicopter, Helicopter.class, \"mFrameBuffer\", frameBuffer);\n+\n+        // mFrameBufferRadiusU is only used to cull off-screen helicopters; a few world units are\n+        // plenty to keep it comfortably inside the viewBounds set up around POSITION.\n+        setField(helicopter, Helicopter.class, \"mFrameBufferRadiusU\", 5f);\n+\n+        Field positionField = Helicopter.class.getDeclaredField(\"mPosition\");\n+        positionField.setAccessible(true);\n+        ((Vector2) positionField.get(helicopter)).set(POSITION, POSITION);\n+\n+        return helicopter;\n+    }\n+\n+    private static TiledMap buildMap(Texture fgTexture) {\n+        TiledMap map = new TiledMap();\n+\n+        TiledMapTileLayer bgLayer = new TiledMapTileLayer(MAP_TILES, MAP_TILES, TILE_PX, TILE_PX);\n+        bgLayer.setName(\"bg\");\n+        map.getLayers().add(bgLayer);\n+\n+        TiledMapTileLayer fgLayer = new TiledMapTileLayer(MAP_TILES, MAP_TILES, TILE_PX, TILE_PX);\n+        fgLayer.setName(\"fg\");\n+        StaticTiledMapTile fgTile = new StaticTiledMapTile(new TextureRegion(fgTexture, TILE_PX, TILE_PX));\n+        // TILE_PX pixels per tile, scaled by Constants.UNIT_FOR_PIXEL (1/20) gives exactly 1 world\n+        // unit per tile, so the tile coordinate matching a world position is the position itself.\n+        for (int dx = -2; dx <= 2; ++dx) {\n+            for (int dy = -2; dy <= 2; ++dy) {\n+                TiledMapTileLayer.Cell cell = new TiledMapTileLayer.Cell();\n+                cell.setTile(fgTile);\n+                fgLayer.setCell((int) POSITION + dx, (int) POSITION + dy, cell);\n+            }\n+        }\n+        map.getLayers().add(fgLayer);\n+\n+        return map;\n+    }\n+\n+    private static void setField(Object target, Class<?> declaringClass, String name, Object value)\n+            throws Exception {\n+        Field field = declaringClass.getDeclaredField(name);\n+        field.setAccessible(true);\n+        field.set(target, value);\n+    }\n+\n+    /** A Track that doesn't load anything from disk: it is built entirely in memory. */\n+    private static class FakeTrack extends Track {\n+        private final TiledMap mMap;\n+\n+        FakeTrack(TiledMap map) {\n+            super(null, \"test-track\", \"Test track\");\n+            mMap = map;\n+        }\n+\n+        @Override\n+        public TiledMap getMap() {\n+            return mMap;\n+        }\n+\n+        @Override\n+        public int[] getExtraBackgroundLayerIndexes() {\n+            return new int[0];\n+        }\n+\n+        @Override\n+        public int[] getForegroundLayerIndexes() {\n+            return new int[] {1};\n+        }\n+\n+        @Override\n+        public float getMapWidth() {\n+            return 2000;\n+        }\n+\n+        @Override\n+        public float getMapHeight() {\n+            return 2000;\n+        }\n+    }\n+}\ndiff --git a/core-tests/src/com/agateau/pixelwheels/racescreen/RacerCameraTest.java b/core-tests/src/com/agateau/pixelwheels/racescreen/RacerCameraTest.java\nnew file mode 100755\nindex 0000000..bae7ba4\n--- /dev/null\n+++ b/core-tests/src/com/agateau/pixelwheels/racescreen/RacerCameraTest.java\n@@ -0,0 +1,95 @@\n+/*\n+ * How the race view follows the player's car: it keeps the car on screen and leaves more room in\n+ * front of the car than behind it, whichever way the car is heading.\n+ *\n+ * The camera updater used by the race screen is driven with a car standing still in the middle of\n+ * a large track, facing various directions, and the resulting camera is inspected.\n+ */\n+package com.agateau.pixelwheels.racescreen;\n+\n+import static org.junit.Assert.assertTrue;\n+import static org.mockito.Mockito.mock;\n+import static org.mockito.Mockito.when;\n+\n+import com.agateau.pixelwheels.GameWorld;\n+import com.agateau.pixelwheels.map.Track;\n+import com.agateau.pixelwheels.racer.Racer;\n+import com.agateau.pixelwheels.racer.Vehicle;\n+import com.badlogic.gdx.graphics.OrthographicCamera;\n+import com.badlogic.gdx.math.Vector2;\n+import org.junit.Test;\n+import org.junit.runner.RunWith;\n+import org.junit.runners.JUnit4;\n+\n+@RunWith(JUnit4.class)\n+public class RacerCameraTest {\n+    private static final float[] HEADINGS = {0, 45, 90, 135, 180, 225, 270, 315};\n+    private static final Vector2 CAR = new Vector2(500, 500);\n+\n+    /** Returns where the view is centered, relative to the car. */\n+    private static Vector2 viewOffset(float heading) {\n+        Track track = mock(Track.class);\n+        when(track.getMapWidth()).thenReturn(1000f);\n+        when(track.getMapHeight()).thenReturn(1000f);\n+        GameWorld world = mock(GameWorld.class);\n+        when(world.getTrack()).thenReturn(track);\n+\n+        Vehicle vehicle = mock(Vehicle.class);\n+        when(vehicle.getPosition()).thenReturn(new Vector2(CAR));\n+        when(vehicle.getX()).thenReturn(CAR.x);\n+        when(vehicle.getY()).thenReturn(CAR.y);\n+        when(vehicle.getAngle()).thenReturn(heading);\n+        when(vehicle.getSpeed()).thenReturn(0f);\n+        Racer racer = mock(Racer.class);\n+        when(racer.getVehicle()).thenReturn(vehicle);\n+        when(racer.getCameraAngle()).thenReturn(heading);\n+        when(racer.getPosition()).thenReturn(new Vector2(CAR));\n+        when(racer.getX()).thenReturn(CAR.x);\n+        when(racer.getY()).thenReturn(CAR.y);\n+\n+        OrthographicCamera camera = new OrthographicCamera();\n+        RacerCameraUpdater updater = new RacerCameraUpdater(world, racer);\n+        updater.init(camera, 1920, 1080);\n+        updater.update(CameraUpdater.IMMEDIATE);\n+\n+        float halfW = camera.viewportWidth * camera.zoom / 2;\n+        float halfH = camera.viewportHeight * camera.zoom / 2;\n+        Vector2 offset = new Vector2(camera.position.x, camera.position.y).sub(CAR);\n+        assertTrue(\n+                \"heading \" + heading + \"°: the car is out of the view (view offset \" + offset + \")\",\n+                Math.abs(offset.x) < halfW && Math.abs(offset.y) < halfH);\n+        return offset;\n+    }\n+\n+    private static float angleBetween(Vector2 direction, float angleDeg) {\n+        float delta = (direction.angleDeg() - angleDeg) % 360;\n+        if (delta < -180) {\n+            delta += 360;\n+        } else if (delta > 180) {\n+            delta -= 360;\n+        }\n+        return Math.abs(delta);\n+    }\n+\n+    @Test\n+    public void viewLooksAheadOfTheCarWhicheverWayItHeads() {\n+        for (float heading : HEADINGS) {\n+            Vector2 offset = viewOffset(heading);\n+            assertTrue(\n+                    \"heading \" + heading + \"°: the view should show more of the road ahead of the\"\n+                            + \" car than behind it (view offset \" + offset + \")\",\n+                    offset.len() > 1);\n+            assertTrue(\n+                    \"heading \" + heading + \"°: the view is shifted towards \" + offset.angleDeg()\n+                            + \"° instead of towards where the car is heading\",\n+                    angleBetween(offset, heading) < 5);\n+        }\n+    }\n+\n+    @Test\n+    public void viewKeepsTheCarOnScreen() {\n+        for (float heading : HEADINGS) {\n+            viewOffset(heading);\n+        }\n+    }\n+}\ndiff --git a/core-tests/src/com/agateau/pixelwheels/testutils/DrawRecorder.java b/core-tests/src/com/agateau/pixelwheels/testutils/DrawRecorder.java\n", "numLines": 926, "startLine": 1, "totalLines": 926}}

